	// description: |
	//   MinConfidence is the minimum confidence (0-1) an llm verdict needs to
	//   count as a match. Defaults to 0.
	MinConfidence float64 `yaml:"min-confidence,omitempty" json:"min-confidence,omitempty" jsonschema:"title=minimum llm confidence,description=Minimum confidence between 0 and 1 for an llm verdict to match"`
	// description: |
	// description: |
	//   Inputs compares several responses instead of a single part, for
	//   checks that are about the difference between responses (blind
	//   boolean injection, user enumeration, IDOR). Each entry is resolved
	//   against the runtime values, so {{body_1}} and {{body_2}} work with
	//   req-condition, and each response is framed separately for the model.
	//   Part is ignored when Inputs is set.
	// examples:
	//   - value: "[]string{\"{{body_1}}\", \"{{body_2}}\"}"
	Inputs []string `yaml:"inputs,omitempty" json:"inputs,omitempty" jsonschema:"title=llm inputs to compare,description=Responses to compare instead of a single part; each entry supports {{...}} interpolation"`

	//   MaxInputTokens caps how much of the response part is sent to the model
	//   for an llm matcher, as an approximate token count.
	MaxInputTokens int `yaml:"max-input-tokens,omitempty" json:"max-input-tokens,omitempty" jsonschema:"title=max llm input tokens,description=Approximate cap on response tokens sent to the model"`
	// description: |
	//   AllowSole permits an llm matcher to be the only matcher on a high or
	//   critical template. Without it such a template is rejected, so a model is
	//   never the sole arbiter of a severe finding by accident.
	AllowSole bool `yaml:"allow-sole,omitempty" json:"allow-sole,omitempty" jsonschema:"title=allow llm as sole matcher,description=Permit an llm matcher to be the only matcher on a high or critical template"`

	// description: |
	//   Encoding specifies the encoding for the words field if any.
	// values:
	//   - "hex"
	Encoding string `yaml:"encoding,omitempty" json:"encoding,omitempty" jsonschema:"title=encoding for word field,description=Optional encoding for the word fields,enum=hex"`
	// description: |
	//   CaseInsensitive enables case-insensitive matches. Default is false.
	// values:
	//   - false
	//   - true
	CaseInsensitive bool `yaml:"case-insensitive,omitempty" json:"case-insensitive,omitempty" jsonschema:"title=use case insensitive match,description=use case insensitive match"`
	// description: |
	//   MatchAll enables matching for all matcher values. Default is false.
	// values:
	//   - false
	//   - true
	MatchAll bool `yaml:"match-all,omitempty" json:"match-all,omitempty" jsonschema:"title=match all values,description=match all matcher values ignoring condition"`
	// description: |
	//  Internal when true hides the matcher from output. Default is false.
	// It is meant to be used in multiprotocol / flow templates to create internal matcher condition without printing it in output.
	// or other similar use cases.
	// values:
	//   - false
	//   - true
	Internal bool `yaml:"internal,omitempty" json:"internal,omitempty" jsonschema:"title=hide matcher from output,description=hide matcher from output"`

	// cached data for the compiled matcher
	condition     ConditionType // todo: this field should be the one used for overridden marshal ops
	matcherType   MatcherType
	binaryDecoded []string
	regexCompiled []*regexp.Regexp
	dslCompiled   []*govaluate.EvaluableExpression
	llmClient     LLMClient
}

// ConditionType is the type of condition for matcher
type ConditionType int

const (
	// ANDCondition matches responses with AND condition in arguments.
	ANDCondition ConditionType = iota + 1
	// ORCondition matches responses with AND condition in arguments.
	ORCondition
)

// ConditionTypes is a table for conversion of condition type from string.
var ConditionTypes = map[string]ConditionType{
	"and": ANDCondition,
	"or":  ORCondition,
}

// Result reverts the results of the match if the matcher is of type negative.
func (matcher *Matcher) Result(data bool) bool {
	if matcher.Negative {
		return !data
	}
	return data
}

// ResultWithMatchedSnippet returns true and the matched snippet, or false and an empty string
func (matcher *Matcher) ResultWithMatchedSnippet(data bool, matchedSnippet []string) (bool, []string) {
	if matcher.Negative {
		return !data, []string{}
	}
	return data, matchedSnippet
}

// NeedsResponse returns true if the matcher reads the full response.
func (matcher *Matcher) NeedsResponse() bool {
	if matcher == nil {
		return false
	}
	if IsResponseVar(matcher.Part) {
		return true
	}
	for _, expr := range matcher.dslCompiled {
		for _, v := range expr.Vars() {
			if IsResponseVar(v) {
				return true
			}
		}
	}
	return MentionsResponse(matcher.DSL, matcher.Words, matcher.Regex)
}

// IsResponseVar reports whether name is the full response or a numbered copy of it.
func IsResponseVar(name string) bool {
	name = strings.ToLower(name)
	return name == "response" || strings.HasPrefix(name, "response_")
}

// MentionsResponse reports whether any value refers to the response by name,
// either as a DSL variable or as a {{response}} placeholder.
func MentionsResponse(values ...[]string) bool {
	for _, list := range values {
		for _, value := range list {
			if strings.Contains(strings.ToLower(value), "response") {
				return true
			}
		}
	}
	return false
}
