	data, err := r.runCommand(true, "", func(cmd *exec.Cmd) {
		cmd.Args = append(cmd.Args[:1], builtArgs...)
		cmd.Env = r.buildEnv(nil)
		if debug {
			cmd.Args = append(cmd.Args, "-debug")
			fmt.Println(cmd.String())
		}
	})
	if debug && len(data) > 0 {
		fmt.Println(string(data))
	}

	if err != nil {
		return "", err
	}

	return string(data), nil
